import re
ansi=re.compile(r'\x1b\[[0-9;]*m')
txt=ansi.sub('',open('main.log',encoding='utf-8',errors='replace').read())
lines=txt.split('\n')
blocks=[]; cur=[]
for l in lines:
    s=l.strip()
    if s.startswith('│') and s.endswith('│'):
        parts=[p.strip() for p in s.split('│')[1:-1]]
        for i in range(0,len(parts)-1,2):
            if parts[i]: cur.append((parts[i],parts[i+1]))
    if 'Train step' in s and 'done' in s:
        blocks.append(cur); cur=[]
for i,b in enumerate(blocks):
    d=dict(b)
    extra={k:v for k,v in d.items() if not k.startswith('ppo_actor') and not k.startswith('timeperf')}
    print(i+1, extra)
